    @EventHandler( payloadType=CreateApplicationEvent.class )
    public void handle( CreateApplicationEvent event) {
	    LOGGER.info("handling CreateApplicationEvent - " + event );
	    Application entity = new Application();
            entity.setApplicationId( event.getApplicationId() );
            entity.setApplicationNumber( event.getApplicationNumber() );
            entity.setSubmissionDate( event.getSubmissionDate() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllApplication( entity );
    }

