    /**
     * Method to retrieve the Application via an ApplicationPrimaryKey.
     * @param 	id Long
     * @return 	Application
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Application handle( FindApplicationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getApplicationId() );
    }
    
    /**
     * Method to retrieve a collection of all Applications
     *
     * @param	query	FindAllApplicationQuery 
     * @return 	List<Application> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Application> handle( FindAllApplicationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindApplication,
 * but only if the id matches
 *
 * @param		entity	Application
 */
	protected void emitFindApplication( Application entity ) {
		LOGGER.info("handling emitFindApplication" );
		
	    queryUpdateEmitter.emit(FindApplicationQuery.class,
	                            query -> query.getFilter().getApplicationId().equals(entity.getApplicationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllApplication
	 * 
	 * @param		entity	Application
	 */
	protected void emitFindAllApplication( Application entity ) {
		LOGGER.info("handling emitFindAllApplication" );
		
	    queryUpdateEmitter.emit(FindAllApplicationQuery.class,
	                            query -> true,
	                            entity);
	}

